-- Conflicts of interest per activity
INSERT INTO activity_conflicts (project_id, activity_id, conflict_number, title, theme, severity, side_a, side_b, why, solutions, sort_order, created_at) VALUES
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', 'c3c7db8c-4193-45aa-b569-e939287cf5ae', 29, 'Gemeente intern: betaalbaarheidsdoel versus sluitende grondexploitatie', 'Geld en programma', 'Hoog', 'Gemeente (volkshuisvesting en grondbedrijf)', 'Gemeente (volkshuisvesting en grondbedrijf)', 'Hetzelfde gemeentelijke grondbedrijf moet zowel betaalbare woningen realiseren als een sluitende grondexploitatie maken. Elke extra sociale huurwoning verlaagt de opbrengst van de grond.', '• Gedifferentieerde grondprijzen per woningcategorie
• Een gemeentelijk fonds voor betaalbaarheid
• Het tekort expliciet accepteren als maatschappelijke investering', 1, now() + 2 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', 'c3c7db8c-4193-45aa-b569-e939287cf5ae', 74, 'Gemeente intern: ruimtelijk beleid versus volkshuisvestingsopgave', 'Procedure en participatie', 'Middel', 'Gemeente (ruimtelijk)', 'Gemeente (volkshuisvesting en grondbedrijf); Gemeentelijke woon- en sociaalbeleidsadviseurs', 'Het ruimtelijk beleid van de gemeente (bouwhoogte, groen, parkeren) kan het aantal woningen beperken. Het volkshuisvestingsdeel van dezelfde gemeente moet juist aantallen en betaalbaarheid halen.', '• Het beleid integraal herzien in het omgevingsplan
• Een gebiedsgerichte afweging', 2, now() + 3 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '4f4f683e-2605-409b-b64f-6798ab664ad8', 11, 'Bouwen buiten stedelijk gebied versus woningbouwopgave', 'Ruimtegebruik', 'Hoog', 'Provincie (ruimtelijk); Provincie (wegen en stikstof)', 'Gemeente (volkshuisvesting en grondbedrijf); Gemeentelijke woon- en sociaalbeleidsadviseurs', 'De provinciale verordening beperkt bouwen buiten bestaand stedelijk gebied om landschap en landbouw te beschermen. Tegelijk verplicht de Wet versterking regie volkshuisvesting gemeenten om voldoende woningen te programmeren. Als binnenstedelijk niet genoeg ruimte is, botsen beide wetten.', '• Binnenstedelijke verdichting en transformatie onderzoeken
• In het regionale volkshuisvestingsprogramma afspraken maken met de provincie over uitleglocaties
• Een goede Ladder-onderbouwing en landschappelijke inpassing als voorwaarde', 1, now() + 22 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '4f4f683e-2605-409b-b64f-6798ab664ad8', 29, 'Gemeente intern: betaalbaarheidsdoel versus sluitende grondexploitatie', 'Geld en programma', 'Hoog', 'Gemeente (volkshuisvesting en grondbedrijf)', 'Gemeente (volkshuisvesting en grondbedrijf)', 'Hetzelfde gemeentelijke grondbedrijf moet zowel betaalbare woningen realiseren als een sluitende grondexploitatie maken. Elke extra sociale huurwoning verlaagt de opbrengst van de grond.', '• Gedifferentieerde grondprijzen per woningcategorie
• Een gemeentelijk fonds voor betaalbaarheid
• Het tekort expliciet accepteren als maatschappelijke investering', 2, now() + 23 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '4f4f683e-2605-409b-b64f-6798ab664ad8', 54, 'Nieuwe ontsluiting versus provinciale en rijkswegen', 'Verkeer, hulpdiensten en afval', 'Middel', 'Gemeentelijke mobiliteitsafdeling', 'Provincie (wegen en stikstof)', 'Als de wijk het best op een provinciale of rijksweg kan aansluiten, beslist de provincie of Rijkswaterstaat. Zij wegen de doorstroming en veiligheid op hun weg zwaarder dan de bereikbaarheid van de wijk.', '• Vroeg overleggen
• Aansluiten via een bestaand kruispunt
• Meebetalen aan een rotonde of ongelijkvloerse kruising', 3, now() + 24 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '4f4f683e-2605-409b-b64f-6798ab664ad8', 74, 'Gemeente intern: ruimtelijk beleid versus volkshuisvestingsopgave', 'Procedure en participatie', 'Middel', 'Gemeente (ruimtelijk)', 'Gemeente (volkshuisvesting en grondbedrijf); Gemeentelijke woon- en sociaalbeleidsadviseurs', 'Het ruimtelijk beleid van de gemeente (bouwhoogte, groen, parkeren) kan het aantal woningen beperken. Het volkshuisvestingsdeel van dezelfde gemeente moet juist aantallen en betaalbaarheid halen.', '• Het beleid integraal herzien in het omgevingsplan
• Een gebiedsgerichte afweging', 4, now() + 25 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '6e345041-e27f-4ad5-9c0b-6aba6230f555', 11, 'Bouwen buiten stedelijk gebied versus woningbouwopgave', 'Ruimtegebruik', 'Hoog', 'Landbouworganisaties en agrariërs', 'Gemeente (volkshuisvesting en grondbedrijf)', 'De provinciale verordening beperkt bouwen buiten bestaand stedelijk gebied om landschap en landbouw te beschermen. Tegelijk verplicht de Wet versterking regie volkshuisvesting gemeenten om voldoende woningen te programmeren. Als binnenstedelijk niet genoeg ruimte is, botsen beide wetten.', '• Binnenstedelijke verdichting en transformatie onderzoeken
• In het regionale volkshuisvestingsprogramma afspraken maken met de provincie over uitleglocaties
• Een goede Ladder-onderbouwing en landschappelijke inpassing als voorwaarde', 1, now() + 54 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '6e345041-e27f-4ad5-9c0b-6aba6230f555', 28, '30% sociale huur en ⅔ betaalbaar versus grondopbrengst en rendement', 'Geld en programma', 'Hoog', 'Gemeente (volkshuisvesting en grondbedrijf)', 'Grond- en vastgoedeigenaren', 'Sociale huur en betaalbare koop leveren een lage grondwaarde op. Met veel goedkope woningen dalen de grondopbrengst en het rendement, terwijl grondeigenaren een hoge prijs willen en banken een sluitende business case eisen. Het plan moet bovendien financieel uitvoerbaar zijn.', '• Verevenen binnen het plan met duurdere koop of vrije sector
• Rijksbijdragen zoals de Woningbouwimpuls
• Gefaseerd programmeren en betaalbaarheid over meerdere projecten verdelen (de wet geldt regionaal en niet per project)', 2, now() + 55 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '6e345041-e27f-4ad5-9c0b-6aba6230f555', 29, 'Gemeente intern: betaalbaarheidsdoel versus sluitende grondexploitatie', 'Geld en programma', 'Hoog', 'Gemeente (volkshuisvesting en grondbedrijf)', 'Gemeente (volkshuisvesting en grondbedrijf)', 'Hetzelfde gemeentelijke grondbedrijf moet zowel betaalbare woningen realiseren als een sluitende grondexploitatie maken. Elke extra sociale huurwoning verlaagt de opbrengst van de grond.', '• Gedifferentieerde grondprijzen per woningcategorie
• Een gemeentelijk fonds voor betaalbaarheid
• Het tekort expliciet accepteren als maatschappelijke investering', 3, now() + 56 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '6e345041-e27f-4ad5-9c0b-6aba6230f555', 35, 'Grondeigenaar versus gemeentelijke planning', 'Geld en programma', 'Middel', 'Grond- en vastgoedeigenaren', 'Gemeente (volkshuisvesting en grondbedrijf)', 'Zonder grond geen woningen. Een eigenaar kan een te hoge prijs vragen of niet willen verkopen, en erfdienstbaarheden kunnen de plaatsing beperken. Onteigening kan, maar duurt lang en is een laatste middel.', '• Vroeg een voorkeursrecht vestigen
• Zelfrealisatie door de eigenaar via een anterieure overeenkomst
• Grondruil', 4, now() + 57 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '6e345041-e27f-4ad5-9c0b-6aba6230f555', 63, 'Behoud landbouwgrond versus natuurcompensatie en woningbouw', 'Natuur, groen en bomen', 'Laag', 'Landbouworganisaties en agrariërs', 'Gemeente (volkshuisvesting en grondbedrijf)', 'Woningbouw en natuurcompensatie gaan allebei vaak ten koste van landbouwgrond. Agrariërs verliezen productiegrond en perspectief.', '• Compensatie op grond met lage landbouwwaarde
• Agrarisch natuurbeheer als combinatie', 5, now() + 58 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '0b0a0dcc-1f00-4545-b886-a8bc499624d6', 29, 'Gemeente intern: betaalbaarheidsdoel versus sluitende grondexploitatie', 'Geld en programma', 'Hoog', 'Gemeente (volkshuisvesting en grondbedrijf)', 'Gemeente (volkshuisvesting en grondbedrijf)', 'Hetzelfde gemeentelijke grondbedrijf moet zowel betaalbare woningen realiseren als een sluitende grondexploitatie maken. Elke extra sociale huurwoning verlaagt de opbrengst van de grond.', '• Gedifferentieerde grondprijzen per woningcategorie
• Een gemeentelijk fonds voor betaalbaarheid
• Het tekort expliciet accepteren als maatschappelijke investering', 1, now() + 85 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '0b0a0dcc-1f00-4545-b886-a8bc499624d6', 32, 'Corporatiecapaciteit versus 30% sociale huur', 'Geld en programma', 'Middel', 'Woningcorporaties, WSW en Aw', 'Gemeente (volkshuisvesting en grondbedrijf); Gemeentelijke woon- en sociaalbeleidsadviseurs', 'De wet vraagt veel sociale huur, maar corporaties zijn gebonden aan de WSW-ratio''s en hun eigen investeringsruimte. Ze moeten ook nog verduurzamen. Niet elke corporatie kan alles financieren wat in het programma staat.', '• Prestatieafspraken met realistische aantallen
• Een lagere grondprijs voor sociale huur
• Samenwerking tussen corporaties of overname door een sterkere corporatie', 2, now() + 86 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '0b0a0dcc-1f00-4545-b886-a8bc499624d6', 33, 'Woningcorporaties intern: lage huren versus financiële ratio''s en kwaliteit', 'Geld en programma', 'Middel', 'Woningcorporaties (verhuur)', 'Woningcorporaties, WSW en Aw', 'Corporaties moeten 95% van de lage inkomens een woning onder de aftoppingsgrens bieden. Tegelijk moeten ze aan de WSW-ratio''s voldoen en willen ze levensloopbestendig bouwen. Lage huren en hoge kwaliteit verlagen de kasstroom.', '• Een mix van huurklassen binnen de sociale huur
• Alleen een deel van de woningen levensloopbestendig maken
• Standaardisatie', 3, now() + 87 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '0b0a0dcc-1f00-4545-b886-a8bc499624d6', 39, 'Toewijzingsregels versus lokale wensen', 'Geld en programma', 'Laag', 'Woningcorporaties (verhuur); Gemeentelijke woon- en sociaalbeleidsadviseurs', 'Toekomstige bewoners', 'Dorpsraden willen vaak dat lokale jongeren voorrang krijgen. Inkomensgrenzen, passend toewijzen en de huisvestingsverordening beperken hoe ver een gemeente of corporatie daarin kan gaan.', '• Een regeling voor lokale binding in de huisvestingsverordening, binnen de wettelijke grenzen
• Duidelijke communicatie over de toewijzingsregels', 4, now() + 88 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '0b0a0dcc-1f00-4545-b886-a8bc499624d6', 72, 'Huurdersinstemming versus collectieve installaties', 'Procedure en participatie', 'Laag', 'Huurdersorganisaties', 'Woningcorporaties (verhuur)', 'Corporaties die een collectieve warmte- of ventilatievoorziening willen, moeten servicekostenbeleid afstemmen met de huurdersorganisatie, die instemmingsrecht heeft. Dat kan keuzes vertragen of tegenhouden.', '• Huurdersorganisaties vroeg betrekken bij het energieconcept
• Een transparante servicekostenberekening', 5, now() + 89 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', 'be5165ce-ab59-4f17-a51a-09632226d052', 15, 'Waterpeil: landbouw versus bodemdaling en fundering', 'Water en bodem', 'Middel', 'Landbouworganisaties en agrariërs', 'Natuur- en milieuorganisaties', 'Agrariërs willen een laag waterpeil voor een draagkrachtige bodem. Een laag peil laat veen oxideren (bodemdaling) en kan houten funderingen aantasten. Natuurorganisaties willen juist een hoog peil voor natte natuur.', '• Hydrologisch scheiden van woonwijk en landbouwpolder (eigen peilvak)
• Woningen op een betonnen paalfundering die ongevoelig is voor het peil
• Een flexibel peilbeheer', 1, now() + 122 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', 'be5165ce-ab59-4f17-a51a-09632226d052', 63, 'Behoud landbouwgrond versus natuurcompensatie en woningbouw', 'Natuur, groen en bomen', 'Laag', 'Landbouworganisaties en agrariërs', 'Natuur- en milieuorganisaties', 'Woningbouw en natuurcompensatie gaan allebei vaak ten koste van landbouwgrond. Agrariërs verliezen productiegrond en perspectief.', '• Compensatie op grond met lage landbouwwaarde
• Agrarisch natuurbeheer als combinatie', 2, now() + 123 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '03f744eb-ab54-4e13-b1f8-66b6dc1c795e', 33, 'Woningcorporaties intern: lage huren versus financiële ratio''s en kwaliteit', 'Geld en programma', 'Middel', 'Woningcorporaties (verhuur)', 'Woningcorporaties, WSW en Aw', 'Corporaties moeten 95% van de lage inkomens een woning onder de aftoppingsgrens bieden. Tegelijk moeten ze aan de WSW-ratio''s voldoen en willen ze levensloopbestendig bouwen. Lage huren en hoge kwaliteit verlagen de kasstroom.', '• Een mix van huurklassen binnen de sociale huur
• Alleen een deel van de woningen levensloopbestendig maken
• Standaardisatie', 1, now() + 161 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '60833732-5b5c-48f5-b6bb-a521ab2052ac', 29, 'Gemeente intern: betaalbaarheidsdoel versus sluitende grondexploitatie', 'Geld en programma', 'Hoog', 'Gemeente (volkshuisvesting en grondbedrijf)', 'Gemeente (volkshuisvesting en grondbedrijf)', 'Hetzelfde gemeentelijke grondbedrijf moet zowel betaalbare woningen realiseren als een sluitende grondexploitatie maken. Elke extra sociale huurwoning verlaagt de opbrengst van de grond.', '• Gedifferentieerde grondprijzen per woningcategorie
• Een gemeentelijk fonds voor betaalbaarheid
• Het tekort expliciet accepteren als maatschappelijke investering', 1, now() + 183 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '60833732-5b5c-48f5-b6bb-a521ab2052ac', 74, 'Gemeente intern: ruimtelijk beleid versus volkshuisvestingsopgave', 'Procedure en participatie', 'Middel', 'Gemeente (ruimtelijk)', 'Gemeente (volkshuisvesting en grondbedrijf); Gemeentelijke woon- en sociaalbeleidsadviseurs', 'Het ruimtelijk beleid van de gemeente (bouwhoogte, groen, parkeren) kan het aantal woningen beperken. Het volkshuisvestingsdeel van dezelfde gemeente moet juist aantallen en betaalbaarheid halen.', '• Het beleid integraal herzien in het omgevingsplan
• Een gebiedsgerichte afweging', 2, now() + 184 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '0fe2ce1a-fb69-4dd7-b57a-93faa89820cf', 14, 'Ophogen versus zetting en bodemdaling', 'Water en bodem', 'Hoog', 'Civieltechnisch adviseur', 'Geotechnisch adviseur', 'Om wateroverlast en overstromingsrisico te beperken wil de civieltechnisch adviseur het maaiveld ophogen. Op slappe klei en veen veroorzaakt ophoogzand juist extra zetting en versnelt het de bodemdaling, zodat straten en tuinen na verloop van tijd weer zakken.', '• Lichtgewicht ophoogmateriaal (EPS, schuimbeton)
• Woningen op palen met een hoger vloerpeil en een lager liggende openbare ruimte die kan inunderen
• Een voorbelasting en een langere wachttijd voor de bouw', 1, now() + 222 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '0fe2ce1a-fb69-4dd7-b57a-93faa89820cf', 76, 'Heien versus trillingen bij omwonenden', 'Bouwfase en logistiek', 'Middel', 'Geotechnisch adviseur', 'Geotechnisch adviseur', 'Op slappe grond is een paalfundering nodig. Heien veroorzaakt trillingen en geluid die bestaande woningen (vaak op houten palen) kunnen beschadigen.', '• Trillingsarme palen (schroefpalen, boorpalen)
• Een nulmeting en monitoring
• Werktijden beperken', 2, now() + 223 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '1e5ec7f9-0664-4c4c-a4bc-65a48b17870d', 14, 'Ophogen versus zetting en bodemdaling', 'Water en bodem', 'Hoog', 'Civieltechnisch adviseur; Klimaatadaptatieadviseur', 'Klimaatadaptatieadviseur', 'Om wateroverlast en overstromingsrisico te beperken wil de civieltechnisch adviseur het maaiveld ophogen. Op slappe klei en veen veroorzaakt ophoogzand juist extra zetting en versnelt het de bodemdaling, zodat straten en tuinen na verloop van tijd weer zakken.', '• Lichtgewicht ophoogmateriaal (EPS, schuimbeton)
• Woningen op palen met een hoger vloerpeil en een lager liggende openbare ruimte die kan inunderen
• Een voorbelasting en een langere wachttijd voor de bouw', 1, now() + 235 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '1e5ec7f9-0664-4c4c-a4bc-65a48b17870d', 4, 'Ondergrondse ruimte: kabels en leidingen versus bomen', 'Ruimtegebruik', 'Middel', 'Gemeente en rioolbeheerder; Civieltechnisch adviseur', 'Klimaatadaptatieadviseur', 'Elektriciteit, drinkwater, telecom, riolering en eventueel een warmtenet hebben elk een eigen tracé met beschermingszones nodig. Bomen hebben ruimte nodig voor hun wortels. In smalle straatprofielen past dat niet allebei, en boomwortels kunnen leidingen beschadigen.', '• Een integraal ondergronds profiel opstellen met vaste stroken (bijv. leidingen onder het trottoir, bomen in de berm)
• Wortelschermen of bomen in boomkratten
• Een bredere groenstrook ten koste van rijbaan of parkeren', 2, now() + 236 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '1e5ec7f9-0664-4c4c-a4bc-65a48b17870d', 67, 'Minder verharding versus parkeren en berijdbaarheid', 'Gezondheid (geluid, lucht, geur)', 'Laag', 'Klimaatadaptatieadviseur', 'Civieltechnisch adviseur', 'Om hitte te beperken willen de klimaatadaptatieadviseur en de GGD minder verharding. Parkeervakken, brede rijbanen en opstelplaatsen voor de brandweer zijn juist verhard.', '• Waterdoorlatende of groene verharding
• Het straatprofiel versmallen waar dat kan
• Bomen boven parkeervakken', 3, now() + 237 * interval '1 microsecond'),
  ('392eb8e2-fc9c-4e08-9e79-508af98a40e9', '7e48d0b9-9e29-491e-ab7a-b94aa284f6e8', 14, 'Ophogen versus zetting en bodemdaling', 'Water en bodem', 'Hoog', 'Klimaatadaptatieadviseur', 'Klimaatadaptatieadviseur', 'Om wateroverlast en overstromingsrisico te beperken wil de civieltechnisch adviseur het maaiveld ophogen. Op slappe klei en veen veroorzaakt ophoogzand juist extra zetting en versnelt het de bodemdaling, zodat straten en tuinen na verloop van tijd weer zakken.', '• Lichtgewicht ophoogmateriaal (EPS, schuimbeton)
• Woningen op palen met een hoger vloerpeil en een lager liggende openbare ruimte die kan inunderen
