-- Version history: everything above as one change
CREATE TEMP TABLE import_ctx ON COMMIT DROP AS
SELECT gen_random_uuid() AS batch_id,
       (SELECT id FROM users WHERE role = 'admin' AND status = 'active' ORDER BY created_at LIMIT 1) AS actor_id;

INSERT INTO history_events (project_id, entity_type, entity_id, op, before, after, actor_id, batch_id, note)
SELECT x.id, 'project', x.id, 'create', NULL, jsonb_build_object(
    'id', x.id, 'name', x.name, 'description', x.description, 'status', x.status,
    'startDate', x.start_date, 'endDate', x.end_date, 'leaderName', x.leader_name, 'leaderEmail', x.leader_email,
    'version', x.version, 'deletedAt', CASE WHEN x.deleted_at IS NULL THEN NULL ELSE to_char(x.deleted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'createdAt', CASE WHEN x.created_at IS NULL THEN NULL ELSE to_char(x.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END, 'updatedAt', CASE WHEN x.updated_at IS NULL THEN NULL ELSE to_char(x.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END), c.actor_id, c.batch_id, 'Sjabloon opgebouwd uit V01 - Stakeholders per fase.xlsx, Belangenverstrengeling_per_fase_woningbouw.xlsx en V02 - Stakeholders bij gebiedsontwikkeling voor woningbouw.docx'
FROM projects x CROSS JOIN import_ctx c WHERE x.id = '392eb8e2-fc9c-4e08-9e79-508af98a40e9' ORDER BY x.created_at;

